-- [R118] Chest Chase update. Paste the WHOLE script into the Command Bar in Edit mode (Play stopped).
-- It checks every script is the exact version it was built for, saves a backup in ServerStorage, then installs.
-- Undo any time: require(game.ServerStorage.ChestChase_R118_Backup.Installer)("undo")   Redo: ...("install")
assert(not game:GetService('RunService'):IsRunning(),'[R118] Stop Play first.')
local storage=game:GetService('ServerStorage')
local existing=storage:FindFirstChild('ChestChase_R118_Backup')
if existing then require(existing:WaitForChild('Installer'))('install');return end
-- ASCII-only transport keeps embedded sources independent of pasted Unicode and indentation.
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local values={};for i=1,#alphabet do values[alphabet:sub(i,i)]=i-1 end
local function decode(text)
    local out={}
    for i=1,#text,4 do
        local a,b,c,d=text:sub(i,i),text:sub(i+1,i+1),text:sub(i+2,i+2),text:sub(i+3,i+3)
        local n=assert(values[a])*262144+assert(values[b])*4096+(values[c] or 0)*64+(values[d] or 0)
        out[#out+1]=string.char(math.floor(n/65536)%256)
        if c~='=' then out[#out+1]=string.char(math.floor(n/256)%256) end
        if d~='=' then out[#out+1]=string.char(n%256) end
    end
    return table.concat(out)
end
local function sha256(text)
    local band,bxor,bnot,rshift,ror=bit32.band,bit32.bxor,bit32.bnot,bit32.rshift,bit32.rrotate
    local k={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2}
    local h={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}
    local bits=#text*8
    text=text..string.char(128)..string.rep(string.char(0),(55-#text)%64)
    local length={};for i=7,0,-1 do length[#length+1]=string.char(math.floor(bits/2^(8*i))%256) end
    text=text..table.concat(length)
    for offset=1,#text,64 do
        local w={}
        for i=0,15 do local a,b,c,d=text:byte(offset+i*4,offset+i*4+3);w[i]=a*16777216+b*65536+c*256+d end
        for i=16,63 do
            local a,b=w[i-15],w[i-2]
            w[i]=(w[i-16]+bxor(ror(a,7),ror(a,18),rshift(a,3))+w[i-7]+bxor(ror(b,17),ror(b,19),rshift(b,10)))%4294967296
        end
        local a,b,c,d,e,f,g,j=table.unpack(h)
        for i=0,63 do
            local t1=(j+bxor(ror(e,6),ror(e,11),ror(e,25))+bxor(band(e,f),band(bnot(e),g))+k[i+1]+w[i])%4294967296
            local t2=(bxor(ror(a,2),ror(a,13),ror(a,22))+bxor(band(a,b),band(a,c),band(b,c)))%4294967296
            j=g;g=f;f=e;e=(d+t1)%4294967296;d=c;c=b;b=a;a=(t1+t2)%4294967296
        end
        for i,v in ipairs({a,b,c,d,e,f,g,j})do h[i]=(h[i]+v)%4294967296 end
    end
    local out={};for _,v in ipairs(h)do out[#out+1]=string.format('%08x',v)end;return table.concat(out)
end

local specs={{Path="ServerScriptService/ChestChaseServer/Config",Class="ModuleScript",BeforeBytes=187916,AfterBytes=187916,BeforeSHA256="a3f9ace3196f65ea1a0efa21fa1d860de7267e0995ffc0da0dc2b78a49c9a55f",AfterSHA256="5210b7906549546ce6fb95f2cdf871805fe03baf336b2a4e18c2642779d2b0ba"},{Path="ServerScriptService/ChestChaseServer/SpeedBoardService",Class="ModuleScript",BeforeBytes=9363,AfterBytes=11108,BeforeSHA256="79dbdef629f10ffd16b8b98c126f7fc7e11c83a7747ce8c3d65d623ccf02affe",AfterSHA256="bc8748a13952aea12061bcd4f42d0c741706b782e223e5a56ea156c7f32138ed"},{Path="StarterPlayer/StarterPlayerScripts/LeaderboardClient",Class="LocalScript",New=true,AfterBytes=11772,AfterSHA256="fd927f961c37b8b1c7f271777a65e97d89722f2ecf2edf37a45f58e1d580d82d"}}
local patches={{Path="ServerScriptService/ChestChaseServer/Config",Patches={{186853,1,table.concat({"OA=="})}}},{Path="ServerScriptService/ChestChaseServer/SpeedBoardService",Patches={{531,13,table.concat({""})},{6819,0,table.concat({""})},{6860,5,table.concat({"c2hvd24="})},{6904,0,table.concat({"aWYgaT5zaG93biB0aGVuIGJyZWFrIGVuZDs="})},{7215,5,table.concat({"c2hvd24="})},{7431,0,table.concat({"LS0gUjExODogdG9wIDEwMCBvbiBib3RoIGJvYXJkcyAocGxheWVycyBzY3JvbGwgdGhlIGJvYXJkIG9uIHRoZWlyIG93biBzY3JlZW4sIExlYWRlcmJvYXJkQ2xpZW50KS4KICA="})},{7519,31,table.concat({"Uy5TaXpl"})},{7633,0,table.concat({"O2xvY2FsIHJlYWRzPTA="})},{7803,0,table.concat({""})},{7835,52,table.concat({"O2xvY2FsIGluZGV4PXRvbnVtYmVyKHNjb3JlKW9yIDAKICAgICAgaWYgI3Jvd3M8MTAgYW5kKG5vdCBjYWNoZWQgb3IgY2FjaGVkLkluZGV4fj1pbmRleClhbmQgcmVhZHM8MTIgdGhlbgogICAgICAgcmVhZHMrPTE="})},{8053,0,table.concat({"LEluZGV4PWluZGV4"})},{8093,0,table.concat({"aWYgbm90IHJlYWRPSyB0aGVu"})},{8153,12,table.concat({"SW5kZXg9PWluZGV4IGFuZCBjYWNoZWQuU2NvcmUgb3IgUy5Gcm9tTG9nKGluZGV4LzEwMDAwMDAwMDAp"})},{8422,2,table.concat({"Uy5TaXpl"})}}},{Path="StarterPlayer/StarterPlayerScripts/LeaderboardClient",Patches={{1,0,table.concat({"","","",""})}}}}
local engineSource=decode(table.concat({"","",""}))
assert(sha256(engineSource)=='05744b2dc9125dc57ec69ee39ea40c20c1a6dcffd488f09faee64da379a8e3b1','[R118] The pasted text was damaged while copying. Nothing changed.')
local editor=game:GetService('ScriptEditorService')
local function unique(parent,name)
 local found,count=nil,0
 for _,child in ipairs(parent:GetChildren())do if child.Name==name then found=child;count+=1 end end
 assert(count==1,'[R118] Missing or duplicated object: '..name..' in '..parent:GetFullName()..'. Nothing changed.');return found
end
local function resolve(path)local item=game;for name in path:gmatch('[^/]+')do item=unique(item,name)end;return item end
local byPath={};for _,p in ipairs(patches)do byPath[p.Path]=p.Patches end
local backup=Instance.new('Folder');backup.Name='ChestChase_R118_Backup'
local sources=Instance.new('Folder');sources.Name='Sources';sources.Parent=backup
for i,spec in ipairs(specs)do
 if spec.New then
  -- A script this update adds. It is created parked inside the backup; the installer moves it into place.
  local parentPath,name=spec.Path:match('^(.*)/([^/]+)$');local home=resolve(parentPath)
  assert(home:FindFirstChild(name)==nil,'[R118] '..spec.Path..' already exists. Nothing changed.')
  local after=''
  for _,p in ipairs(byPath[spec.Path])do after=after..decode(p[3])end
  assert(#after==spec.AfterBytes and sha256(after)==spec.AfterSHA256,'[R118] Patch check failed for '..spec.Path..'. Nothing changed.')
  local entry=Instance.new('Folder');entry.Name=string.format('%02d',i);entry:SetAttribute('Path',spec.Path);entry:SetAttribute('New',true);entry.Parent=sources
  local b=Instance.new('StringValue');b.Name='After';b.Value=after;b.Parent=entry
  local item=Instance.new(spec.Class);item.Name=name;item.Source=after;item.Parent=entry
  local t=Instance.new('ObjectValue');t.Name='Target';t.Value=item;t.Parent=entry
  continue
 end
 local item=resolve(spec.Path)
 assert(item.ClassName==spec.Class,'[R118] '..spec.Path..' is a '..item.ClassName..', expected '..spec.Class..'. Nothing changed.')
 local before=editor:GetEditorSource(item)
 assert(item.Source==before,'[R118] Close or save unsaved edits in '..spec.Path..' first. Nothing changed.')
 assert(#before==spec.BeforeBytes and sha256(before)==spec.BeforeSHA256,'[R118] '..spec.Path..' is not the version this update was built for. Nothing changed.')
 local after=before;local list=byPath[spec.Path]
 table.sort(list,function(a,b)return a[1]>b[1]end)
 for _,p in ipairs(list)do after=after:sub(1,p[1]-1)..decode(p[3])..after:sub(p[1]+p[2])end
 assert(#after==spec.AfterBytes and sha256(after)==spec.AfterSHA256,'[R118] Patch check failed for '..spec.Path..'. Nothing changed.')
 local entry=Instance.new('Folder');entry.Name=string.format('%02d',i);entry:SetAttribute('Path',spec.Path);entry.Parent=sources
 local a=Instance.new('StringValue');a.Name='Before';a.Value=before;a.Parent=entry
 local b=Instance.new('StringValue');b.Name='After';b.Value=after;b.Parent=entry
 local t=Instance.new('ObjectValue');t.Name='Target';t.Value=item;t.Parent=entry
end
local installer=Instance.new('ModuleScript');installer.Name='Installer';installer.Source=engineSource;installer.Parent=backup
backup:SetAttribute('SourceCount',#specs);backup:SetAttribute('State','Built');backup.Parent=storage
require(installer)('install')
print('[R118] Backup: ServerStorage.ChestChase_R118_Backup   Undo: require(game.ServerStorage.ChestChase_R118_Backup.Installer)("undo")')
